  /* 盘上有食物 → 换「有食物盘」贴图（煎蛋培根盘 / 包子盘），且不再叠一份食材贴图 */
  const d5 = b5.B.debug;
  b5.record.drawImage.length = 0;
  d5.drop("egg", null); d5.plateNow(3);
  b5.pump(1);
  const n2 = b5.record.drawImage.map(x => x.src.split("/").pop());
  A(n2.indexOf("plate_egg_bacon.png") >= 0, "煎蛋落到盘上 → 用 plate_egg_bacon.png（煎蛋培根盘）");
  /* 「不再叠一份食材贴图」必须只看**盘位那一块**：底排食材桶每帧都要画 egg.png，
     整帧里数 egg.png 是数不准的。 */
  const pbox3 = b5.B.plateBox(3);
  const inPlate = (name) => b5.record.drawImage.some(r => r.src.split("/").pop() === name &&
    (r.dx + r.dw / 2) >= pbox3.x && (r.dx + r.dw / 2) <= pbox3.x + pbox3.w &&
    (r.dy + r.dh / 2) >= pbox3.y && (r.dy + r.dh / 2) <= pbox3.y + pbox3.h);
  A(!inPlate("egg.png"), "盘贴图自带食物时，盘位框里不再叠一份食材贴图（避免一盘两样）",
    "盘位框 " + JSON.stringify(pbox3));
  /* 反过来验一次：没有专属盘贴图的食材（白粥）→ 盘位仍是「空盘 + 食物贴图」 */
  const dropped5 = d5.drop("congee", null), plated5 = d5.plateNow(0);
  b5.record.drawImage.length = 0;
  b5.pump(1);
  const pbox0 = b5.B.plateBox(0);
  const inBox0 = (name) => b5.record.drawImage.filter(r => r.src.split("/").pop() === name &&
    (r.dx + r.dw / 2) >= pbox0.x && (r.dx + r.dw / 2) <= pbox0.x + pbox0.w &&
    (r.dy + r.dh / 2) >= pbox0.y && (r.dy + r.dh / 2) <= pbox0.y + pbox0.h);
  A(inBox0("congee.png").length > 0,
    "白粥落盘 → 盘位是「plate_empty + 食物贴图」（没有专属盘贴图的食材照旧这样画）",
    "drop=" + dropped5 + " plateNow=" + plated5 + " plateTex=" + d5.plates().map(p => p.food + ":" + p.state).join(",") +
    " 盘位里的图：" + b5.record.drawImage.filter(r => (r.dx + r.dw / 2) >= pbox0.x && (r.dx + r.dw / 2) <= pbox0.x + pbox0.w).map(r => r.src.split("/").pop()).join(","));
  b5.record.drawImage.length = 0;
  d5.drop("bun", null); d5.plateNow(6);
  b5.pump(1);
  A(b5.record.drawImage.map(x => x.src.split("/").pop()).indexOf("plate_bun.png") >= 0,
    "包子落到盘上 → 用 plate_bun.png（包子盘）");
  d5.burnPlate(6);
  b5.record.drawImage.length = 0;
  b5.pump(1);
  A(b5.record.drawImage.some(x => /art\/icons\/ui\/cross\.png$/.test(x.src)),
    "盘上那份糊了 → 画红叉贴图 ui/cross.png（矢量红叉只是缺图时的兜底）");
  b5.B.dispose();
}
